<template>
  <section class="payments-workspace" aria-labelledby="payments-title">
    <div class="payments-lead">
      <div><p class="payments-kicker">Today · Africa/Kampala</p><h2 id="payments-title">Daily payments</h2><p>Monitor today’s collection attempts, resolve exceptions, and manage linked subscriptions.</p><small v-if="lastUpdated" class="last-updated">Updated {{ dateTime(lastUpdated) }} · refreshes every 30 seconds</small></div>
      <button type="button" class="refresh-button" :disabled="loading" @click="loadPayments(meta.current_page || 1)">{{ loading ? 'Refreshing…' : 'Refresh payments' }}</button>
    </div>

    <div class="ledger-shell">
      <div class="ledger-toolbar">
        <label class="search-field"><span class="sr-only">Search payments</span><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg><input v-model.trim="filters.search" type="search" placeholder="Search customer, phone, reference, or transaction ID" @input="queueSearch" /></label>
        <label class="select-field"><span>Status</span><select v-model="filters.status" @change="applyFilters"><option value="">All statuses</option><option value="pending">Pending</option><option value="confirmed">Confirmed</option><option value="failed">Failed</option></select></label>
      </div>
      <p v-if="error" class="ledger-error" role="alert">{{ error }} <button type="button" @click="loadPayments(meta.current_page || 1)">Try again</button></p>

      <div class="table-wrap" :class="{ 'is-loading': loading }">
        <table class="payment-table">
          <thead><tr><th>Attempted</th><th>Customer</th><th>Package</th><th>Amount</th><th>Gateway</th><th>Reference</th><th>Status</th><th><span class="sr-only">Action</span></th></tr></thead>
          <tbody>
            <tr v-for="payment in payments" :key="payment.id" @click="openPayment(payment)">
              <td data-label="Attempted"><time>{{ dateTime(payment.created_at) }}</time></td>
              <td data-label="Customer"><strong>{{ payment.user?.username || 'Unknown member' }}</strong><small>{{ payment.user?.phone || payment.phone || '—' }}</small></td>
              <td data-label="Package"><strong>{{ packageName(payment) }}</strong><small>{{ capitalize(payment.plan_type) }}</small></td>
              <td data-label="Amount" class="amount-cell">{{ money(payment.amount) }}</td>
              <td data-label="Gateway"><strong>{{ (payment.provider || payment.payment_method || '—').toUpperCase() }}</strong><small>{{ (payment.payment_method || '—').toUpperCase() }}</small></td>
              <td data-label="Reference"><code>{{ payment.payment_reference || payment.transaction_id || '—' }}</code></td>
              <td data-label="Status"><span :class="['status-badge', 'status-' + payment.status]">{{ payment.status }}</span></td>
              <td><button type="button" class="view-button" @click.stop="openPayment(payment)">View</button></td>
            </tr>
            <tr v-if="!loading && !payments.length"><td colspan="8" class="empty-row"><strong>No payments today</strong><span>New attempts will appear here automatically.</span></td></tr>
          </tbody>
        </table>
        <div v-if="loading" class="table-loading" aria-label="Loading payments"><span></span><span></span><span></span></div>
      </div>

      <footer class="pagination" aria-label="Payment pagination">
        <div class="pagination-summary">Showing <strong>{{ meta.from || 0 }}–{{ meta.to || 0 }}</strong> of <strong>{{ number(meta.total) }}</strong></div>
        <div class="page-controls"><button type="button" :disabled="meta.current_page <= 1 || loading" @click="loadPayments(meta.current_page - 1)" aria-label="Previous page">←</button><button v-for="page in visiblePages" :key="page" type="button" :class="{ active: page === meta.current_page }" :disabled="loading" @click="loadPayments(page)">{{ page }}</button><button type="button" :disabled="meta.current_page >= meta.last_page || loading" @click="loadPayments(meta.current_page + 1)" aria-label="Next page">→</button></div>
        <label class="rows-select"><span>Rows</span><select v-model.number="filters.perPage" @change="applyFilters"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option></select></label>
      </footer>
    </div>

    <transition name="drawer-fade"><button v-if="drawerOpen" type="button" class="drawer-backdrop" aria-label="Close payment details" @click="closeDrawer"></button></transition>
    <transition name="drawer-slide">
      <aside v-if="drawerOpen" class="payment-drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title">
        <div class="drawer-head"><div><span>Payment #{{ selected?.id }}</span><h3 id="drawer-title">{{ selected?.user?.username || 'Payment details' }}</h3></div><button type="button" class="drawer-close" aria-label="Close payment details" @click="closeDrawer">×</button></div>
        <div v-if="detailLoading" class="drawer-loading">Loading payment details…</div>
        <template v-else-if="selected">
          <div class="drawer-amount"><span>Amount</span><strong>{{ money(selected.amount) }}</strong><em :class="['status-badge', 'status-' + selected.status]">{{ selected.status }}</em></div>
          <dl class="detail-grid">
            <div><dt>Customer</dt><dd>{{ selected.user?.username || 'Unknown' }}</dd></div><div><dt>Phone</dt><dd>{{ selected.user?.phone || selected.phone || '—' }}</dd></div>
            <div><dt>Package</dt><dd>{{ packageName(selected) }}</dd></div><div><dt>Plan</dt><dd>{{ capitalize(selected.plan_type) }}</dd></div>
            <div><dt>Gateway</dt><dd>{{ (selected.provider || '—').toUpperCase() }}</dd></div><div><dt>Method</dt><dd>{{ (selected.payment_method || '—').toUpperCase() }}</dd></div>
            <div class="detail-wide"><dt>Payment reference</dt><dd><code>{{ selected.payment_reference || '—' }}</code></dd></div><div class="detail-wide"><dt>Transaction ID</dt><dd><code>{{ selected.transaction_id || '—' }}</code></dd></div>
            <div><dt>Attempted</dt><dd>{{ dateTime(selected.created_at) }}</dd></div><div><dt>Completed</dt><dd>{{ dateTime(selected.confirmed_at || selected.failed_at) }}</dd></div>
            <div v-if="selected.failure_reason" class="detail-wide detail-failure"><dt>Failure reason</dt><dd>{{ selected.failure_reason }}</dd></div>
          </dl>
          <section v-if="selected.subscription" class="subscription-section"><div class="drawer-section-head"><span>Linked subscription</span><strong>{{ capitalize(selected.subscription.status) }}</strong></div><p>{{ selected.subscription.group?.name || capitalize(selected.subscription.plan_type) }} · expires {{ dateTime(selected.subscription.expires_at) }}</p></section>
          <p v-if="actionError" class="drawer-error" role="alert">{{ actionError }}</p><p v-if="actionNotice" class="drawer-notice" role="status">{{ actionNotice }}</p>
          <section class="drawer-actions">
            <h4>Payment actions</h4><label v-if="selected.status !== 'confirmed'"><span>Provider transaction ID <small>(optional)</small></span><input v-model.trim="transactionId" type="text" placeholder="Enter transaction ID" /></label>
            <div v-if="selected.status !== 'confirmed'" class="action-pair"><button type="button" class="action-confirm" :disabled="actionLoading" @click="reconcile('success')">Mark confirmed</button><button type="button" class="action-fail" :disabled="actionLoading" @click="reconcile('failed')">Mark failed</button></div>
            <div v-if="selected.subscription" class="action-pair secondary-actions"><button type="button" :disabled="actionLoading" @click="renew">Renew access</button><button v-if="selected.subscription.status === 'active'" type="button" :disabled="actionLoading" @click="revoke">Revoke access</button></div>
            <button v-if="selected.subscription && selected.subscription.status !== 'pending'" type="button" class="delete-action" :disabled="actionLoading" @click="deleteSubscription">Remove subscription record</button>
          </section>
        </template>
      </aside>
    </transition>
  </section>
</template>

<script>
import adminApi from '../../utils/adminApi'
export default {
  name: 'PaymentsOverview',
  props: { focusSubscriptionId: { type: [Number, String], default: null } },
  data() { return { payments: [], loading: true, error: '', filters: { search: '', status: '', perPage: 10 }, meta: { current_page: 1, last_page: 1, per_page: 10, total: 0, from: 0, to: 0 }, selected: null, drawerOpen: false, detailLoading: false, actionLoading: false, actionError: '', actionNotice: '', transactionId: '', searchTimer: null, refreshTimer: null, lastUpdated: null } },
  computed: {
    visiblePages() { const last = Number(this.meta.last_page || 1); const current = Number(this.meta.current_page || 1); const start = Math.max(1, Math.min(current - 2, last - 4)); const end = Math.min(last, start + 4); return Array.from({ length: end - start + 1 }, (_, index) => start + index) }
  },
  watch: { focusSubscriptionId: { immediate: true, handler(id) { if (id) this.openFocusedPayment(id) } } },
  async mounted() { window.addEventListener('keydown', this.onKeydown); document.addEventListener('visibilitychange', this.onVisibilityChange); await this.loadPayments(1); this.refreshTimer = window.setInterval(() => { if (!document.hidden && !this.drawerOpen) this.loadPayments(this.meta.current_page || 1, true) }, 30000) },
  beforeUnmount() { window.clearTimeout(this.searchTimer); window.clearInterval(this.refreshTimer); window.removeEventListener('keydown', this.onKeydown); document.removeEventListener('visibilitychange', this.onVisibilityChange); document.body.style.overflow = '' },
  methods: {
    requestParams(page = 1) { const params = { page, per_page: this.filters.perPage, period: 'today' }; if (this.filters.search) params.search = this.filters.search; if (this.filters.status) params.status = this.filters.status; return params },
    async loadPayments(page = 1, quiet = false) { if (!quiet) this.loading = true; this.error = ''; try { const { data } = await adminApi.get('/api/payments', { params: this.requestParams(page) }); this.payments = data.data || []; this.meta = { current_page: data.current_page, last_page: data.last_page, per_page: data.per_page, total: data.total, from: data.from || 0, to: data.to || 0 }; this.lastUpdated = new Date().toISOString() } catch (error) { this.error = error.response?.data?.message || 'Today’s payments could not be loaded.' } finally { this.loading = false } },
    queueSearch() { window.clearTimeout(this.searchTimer); this.searchTimer = window.setTimeout(this.applyFilters, 350) },
    async applyFilters() { await this.loadPayments(1) },
    onVisibilityChange() { if (!document.hidden) this.loadPayments(this.meta.current_page || 1, true) },
    async openFocusedPayment(subscriptionId) { try { const { data } = await adminApi.get('/api/payments', { params: { subscription_id: subscriptionId, per_page: 10 } }); if (data.data?.[0]) this.openPayment(data.data[0]) } catch { /* Notification navigation still lands on the ledger. */ } },
    async openPayment(payment) { this.selected = payment; this.drawerOpen = true; this.detailLoading = true; this.actionError = ''; this.actionNotice = ''; this.transactionId = payment.transaction_id || ''; document.body.style.overflow = 'hidden'; try { this.selected = (await adminApi.get(`/api/payments/${payment.id}`)).data; this.transactionId = this.selected.transaction_id || '' } catch (error) { this.actionError = error.response?.data?.message || 'Payment details could not be loaded.' } finally { this.detailLoading = false } },
    closeDrawer() { this.drawerOpen = false; this.selected = null; this.actionError = ''; document.body.style.overflow = '' },
    onKeydown(event) { if (event.key === 'Escape' && this.drawerOpen) this.closeDrawer() },
    async afterAction(message) { this.actionNotice = message; await this.loadPayments(this.meta.current_page); if (this.selected?.id) this.selected = (await adminApi.get(`/api/payments/${this.selected.id}`)).data },
    async reconcile(status) { if (!window.confirm(status === 'success' ? 'Mark this payment as confirmed?' : 'Mark this payment as failed?')) return; this.actionLoading = true; this.actionError = ''; this.actionNotice = ''; try { await adminApi.post('/api/payments/reconcile', { reference: this.selected.payment_reference, subscriptionId: this.selected.subscription_id, status, transactionId: this.transactionId || null, force: true }); await this.afterAction(status === 'success' ? 'Payment confirmed and access updated.' : 'Payment marked as failed.') } catch (error) { this.actionError = error.response?.data?.message || 'The payment could not be updated.' } finally { this.actionLoading = false } },
    async renew() { await this.subscriptionAction(() => adminApi.post(`/api/subscriptions/${this.selected.subscription_id}/renew`), 'Subscription renewed.') },
    async revoke() { if (!window.confirm('Revoke access for this subscription?')) return; await this.subscriptionAction(() => adminApi.patch(`/api/subscriptions/${this.selected.subscription_id}`, { status: 'rejected', rejectionReason: 'Access revoked by admin' }), 'Subscription access revoked.') },
    async subscriptionAction(request, success) { this.actionLoading = true; this.actionError = ''; this.actionNotice = ''; try { await request(); await this.afterAction(success) } catch (error) { this.actionError = error.response?.data?.message || 'The subscription could not be updated.' } finally { this.actionLoading = false } },
    async deleteSubscription() { if (!window.confirm('Remove this subscription record? The payment ledger will be preserved.')) return; this.actionLoading = true; this.actionError = ''; try { await adminApi.delete(`/api/subscriptions/${this.selected.subscription_id}`); this.closeDrawer(); await this.loadPayments(this.meta.current_page) } catch (error) { this.actionError = error.response?.data?.message || 'The subscription could not be removed.' } finally { this.actionLoading = false } },
    packageName(payment) { return payment.subscription?.group?.name || this.capitalize(payment.plan_type) || '—' }, capitalize(value) { const text = String(value || ''); return text ? text.charAt(0).toUpperCase() + text.slice(1) : '—' }, money(value) { return `${Number(value || 0).toLocaleString('en-UG')} UGX` }, number(value) { return Number(value || 0).toLocaleString('en-UG') }, dateTime(value) { return value ? new Date(value).toLocaleString('en-UG', { dateStyle: 'medium', timeStyle: 'short' }) : '—' }
  }
}
</script>

